#!/bin/bash
# tb/run_gate_sdf.sh — F4: delay-annotated (SDF) gate-level simulation.
#
# Uses the upstream Nangate45 Verilog models (synth/nangate45_upstream.v,
# which carry `specify` blocks) with SDF back-annotation from synth/mcu.sdf
# (generated by synth/gen_sdf.py from the liberty timing arcs).
#
# Behavioral SRAM/ROM models stay zero-delay (declared abstraction, same as
# F2/F3). Icarus only — Verilator cannot do SDF.
#
# Strategy: START SMALL. Phase 1 = hello.hex (validates annotation + basic
# function). Phase 2 = pingpong.hex (FreeRTOS). The 4-message app subset runs
# only if the small phases prove the flow AND runtime allows.
#
# Env overrides: CLK_PERIOD_NS (default 20), TIMEOUT_S (default 3600),
#   PHASE (hello|pingpong|app), SEED (for app phase).
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

PHASE="${PHASE:-hello}"
CLK_PERIOD_NS="${CLK_PERIOD_NS:-20}"
TIMEOUT_S="${TIMEOUT_S:-3600}"
OUT=build/gate_sdf
LOG=tb/logs/gate_sdf_${PHASE}.log
SDF=synth/mcu.sdf
UPSTREAM=synth/nangate45_upstream.v
NETLIST=synth/mcu_netlist.v
mkdir -p "$OUT" tb/logs results/raw

echo "F4: SDF-annotated gate sim, phase=$PHASE, clk=${CLK_PERIOD_NS}ns"

# ---- prerequisites ----
[ -f "$SDF" ] || { echo "F4: FAIL: SDF missing: $SDF (run: python3 synth/gen_sdf.py)"; exit 1; }
[ -f "$UPSTREAM" ] || { echo "F4: FAIL: upstream models missing: $UPSTREAM"; exit 1; }
[ -f "$NETLIST" ] || { echo "F4: FAIL: netlist missing"; exit 1; }

# ---- SDF annotation audit: every CELL in the SDF must match a specify
# ---- block in the upstream models (fail closed on silent non-annotation) ----
echo "F4: auditing SDF-vs-model specify coverage"
python3 - "$SDF" "$UPSTREAM" <<'EOF'
import re, sys
sdf_path, models_path = sys.argv[1], sys.argv[2]
with open(sdf_path) as f: sdf = f.read()
with open(models_path) as f: mods = f.read()
sdf_types = set(re.findall(r'\(CELLTYPE\s+"(\w+)"', sdf))
# models with specify blocks
has_spec = set()
for m in re.finditer(r'^module\s+(\w+)', mods, re.M):
    e = mods.index('endmodule', m.end())
    if 'specify' in mods[m.end():e]:
        has_spec.add(m.group(1))
missing = sorted(t for t in sdf_types if t not in has_spec)
print(f"F4: SDF cell types: {len(sdf_types)}, models with specify: {len(has_spec)}")
if missing:
    print(f"F4: FAIL: SDF references cell types without specify blocks: {missing[:10]}")
    sys.exit(1)
print("F4: SDF specify coverage OK")
EOF
[ $? -eq 0 ] || exit 1

case "$PHASE" in
  hello)
    FW_HEX=fw/build/hello.hex
    EXPECT="TEST hello PASS"
    TIMEOUT_CYCLES=2000000
    [ -f "$FW_HEX" ] || { echo "F4: building hello"; make -C fw APP=hello || exit 1; }
    ;;
  pingpong)
    FW_HEX=fw/build/pingpong.hex
    EXPECT="MARK pong"
    TIMEOUT_CYCLES=10000000
    [ -f "$FW_HEX" ] || { echo "F4: building pingpong"; make -C fw APP=pingpong || exit 1; }
    ;;
  *)
    echo "F4: FAIL: unknown PHASE=$PHASE"; exit 1
    ;;
esac

echo "F4: iverilog SDF build (upstream models + netlist + behavioral memories)"
iverilog -g2012 -o "$OUT/tb_gate_sdf.vvp" \
  "$UPSTREAM" "$NETLIST" rtl/bootrom.sv rtl/sram.sv tb/tb_gate_sdf.sv 2>&1 | tee "$LOG.build"
[ ${PIPESTATUS[0]} -eq 0 ] || { echo "F4: FAIL: compile error"; exit 1; }

# fail closed on SDF annotation problems
if grep -q "Omitting \$sdf_annotate" "$LOG.build"; then
  echo "F4: FAIL: Icarus omitted \$sdf_annotate (specify blocks not elaborated)"
  exit 1
fi

echo "F4: vvp tb_gate_sdf (SDF-annotated) — clk=${CLK_PERIOD_NS}ns"
timeout "$TIMEOUT_S" vvp "$OUT/tb_gate_sdf.vvp" \
  "+hex=$FW_HEX" "+expect=$EXPECT" "+clk_period_ns=$CLK_PERIOD_NS" \
  "+sdf=$SDF" "+timeout_cycles=$TIMEOUT_CYCLES" 2>&1 | tee "$LOG"
rc=${PIPESTATUS[0]}
echo "F4: vvp exit code = $rc"
[ $rc -eq 0 ] || { echo "F4: FAIL: gate sim nonzero exit"; exit 1; }

# timing violations: upstream models' $setuphold fire NOTIFIER + warnings
if grep -qiE "setup.*violation|hold.*violation|NOTIFIER|timing.*check.*fail" "$LOG"; then
  echo "F4: WARNING: timing-check violations detected (see log)"
  grep -iE "setup.*violation|hold.*violation" "$LOG" | head -5
fi

grep -q "TB_SDF: SIM PASS" "$LOG" || { echo "F4: FAIL: sim verdict missing"; exit 1; }
echo "F4: phase $PHASE PASS (SDF-annotated, clk=${CLK_PERIOD_NS}ns)"
